<?php declare(strict_types=1); namespace App\Model\Table; use Cake\ORM\Table; use Cake\Validation\Validator; class ParqueaderosTable extends Table { /** Configures parking records. */ public function initialize(array $config):void { parent::initialize($config);$this->setTable('parqueaderos');$this->hasMany('AsignacionesParqueaderos',['foreignKey'=>'parqueadero_id']); } /** Validates parking records. */ public function validationDefault(Validator $v):Validator { return $v->notEmptyString('code')->notEmptyString('vehicle_type')->inList('vehicle_type',['car','motorcycle']); } }
